import json
import sqlite3
import subprocess
import sys
import logging
from typing import Dict, Any

def validate_config(config: Dict[str, Any]) -> None:
    required_keys = {'database_path', 'jobs_table', 'log_file'}
    if not required_keys.issubset(config.keys()):
        raise ValueError("config error: missing required keys")

    if not all(isinstance(v, str) for v in config.values()):
        raise ValueError("config error: all values must be strings")

def setup_logging(log_file: str) -> None:
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(message)s'
    )

def process_jobs(config: Dict[str, str]) -> None:
    db_path = config['database_path']
    jobs_table = config['jobs_table']
    log_file = config['log_file']

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        print(f"database error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        cursor.execute(f"SELECT id, command FROM {jobs_table} WHERE status = 'pending' ORDER BY id ASC")
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"database error: {e}", file=sys.stderr)
        sys.exit(1)

    failed_jobs = False

    for row in rows:
        job_id, command = row
        output = ""

        try:
            result = subprocess.run(
                command,
                shell=True,
                check=False,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            output = result.stdout + result.stderr
        except Exception as e:
            output = f"Command execution failed: {str(e)}"
            failed_jobs = True

        status = 'done' if result.returncode == 0 else 'failed'

        try:
            cursor.execute(
                f"UPDATE {jobs_table} SET status = ?, output = ? WHERE id = ?",
                (status, output, job_id)
            )
            conn.commit()
        except sqlite3.Error as e:
            print(f"database error: {e}", file=sys.stderr)
            sys.exit(1)

        try:
            with open(log_file, 'a') as f:
                f.write(f"id={job_id} status={status} output={output}\n")
        except IOError as e:
            print(f"log error: {e}", file=sys.stderr)
            sys.exit(1)

    conn.close()

    if failed_jobs:
        sys.exit(1)
    else:
        sys.exit(0)

def main():
    if len(sys.argv) != 2:
        print("config error: missing config file", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as f:
            config = json.load(f)
    except json.JSONDecodeError:
        print("config error: invalid JSON", file=sys.stderr)
        sys.exit(1)
    except IOError:
        print("config error: missing config file", file=sys.stderr)
        sys.exit(1)

    try:
        validate_config(config)
    except ValueError as e:
        print(e, file=sys.stderr)
        sys.exit(1)

    process_jobs(config)

if __name__ == "__main__":
    main()
